-- READ ONLY. Table rows prove presence only, not CHECK/FK/index/column parity.
SELECT 'table_presence' AS kind,name,to_regclass('public.'||name) IS NOT NULL AS matches
 FROM jsonb_array_elements_text($inventory$["subscription_rule_proposals","subscription_payment_assistance_requests","student_direct_live_reviews","student_direct_live_obligations","student_direct_live_attempts","student_direct_live_events","student_direct_live_release_requests","student_direct_live_release_decisions","student_direct_live_review_bindings","bro_term_commission_entitlements"]$inventory$::jsonb) n(name)
UNION ALL SELECT 'function',e.name,COALESCE((p.oid IS NOT NULL AND p.prokind='f' AND p.pronargs=0 AND p.prorettype='pg_catalog.trigger'::regtype
 AND NOT p.proretset AND NOT p.prosecdef AND p.provolatile='v' AND NOT p.proisstrict
 AND NOT p.proleakproof AND p.proparallel='u' AND p.proconfig IS NULL AND l.lanname='plpgsql'
 AND md5(regexp_replace(replace(p.prosrc,E'\r\n',E'\n'),'^[[:space:]]+|[[:space:]]+$','','g'))=e.body_md5),false)
  FROM jsonb_to_recordset($inventory$[{"name":"guard_student_direct_history","body_md5":"06020fe5a25c579f9157746f4ba847b0"},{"name":"guard_student_direct_attempt","body_md5":"9ba4c246e69a19d4a20d05acd57cdfef"},{"name":"guard_bro_term_commission_history","body_md5":"e18a68b527bc1434fbc86b0abe969f23"},{"name":"guard_bro_term_commission_scope","body_md5":"6803a3b7173c3d9e677d35616a789046"}]$inventory$::jsonb) AS e(name text,body_md5 text) LEFT JOIN pg_proc p ON p.oid=to_regprocedure('public.'||e.name||'()')
 LEFT JOIN pg_language l ON l.oid=p.prolang
UNION ALL SELECT 'trigger',e.name,COALESCE(t.tgenabled='O' AND t.tgtype=e.type
 AND t.tgfoid=to_regprocedure('public.'||e.fn||'()') AND NOT t.tgisinternal
 AND t.tgnargs=0 AND t.tgconstraint=0 AND t.tgqual IS NULL AND t.tgattr::text='' AND t.tgparentid=0,false)
 FROM jsonb_to_recordset($inventory$[{"name":"student_direct_review_history","events":"UPDATE OR DELETE","table":"student_direct_live_reviews","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"student_direct_obligation_history","events":"UPDATE OR DELETE","table":"student_direct_live_obligations","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"student_direct_event_history","events":"UPDATE OR DELETE","table":"student_direct_live_events","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"student_direct_attempt_history","events":"UPDATE OR DELETE","table":"student_direct_live_attempts","level":"ROW","fn":"guard_student_direct_attempt","type":27},{"name":"student_direct_release_request_history","events":"UPDATE OR DELETE","table":"student_direct_live_release_requests","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"student_direct_release_decision_history","events":"UPDATE OR DELETE","table":"student_direct_live_release_decisions","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"student_direct_release_binding_history","events":"UPDATE OR DELETE","table":"student_direct_live_review_bindings","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"bro_term_commission_append_only","events":"UPDATE OR DELETE","table":"bro_term_commission_entitlements","level":"ROW","fn":"guard_bro_term_commission_history","type":27},{"name":"bro_term_commission_scope_guard","events":"INSERT","table":"bro_term_commission_entitlements","level":"ROW","fn":"guard_bro_term_commission_scope","type":7}]$inventory$::jsonb) e(name text,"table" text,fn text,type int)
 LEFT JOIN pg_trigger t ON t.tgrelid=to_regclass('public.'||e."table") AND t.tgname=e.name
ORDER BY kind,name;
